function getBottomGroupCount(col) {
  if (col.length === 0) return 0;
  const c = col[col.length - 1];
  let k = 0;
  for (let i = col.length - 1; i >= 0; i--) {
    if (col[i] === c) k++; else break;
  }
  return k;
}

function findColTarget(columns, color, startIdx) {
  const n = columns.length;
  for (let s = 1; s < n; s++) {
    const idx = (startIdx + s) % n;
    if (columns[idx].length > 0 && columns[idx][columns[idx].length - 1] === color) return idx;
  }
  for (let s = 1; s < n; s++) {
    const idx = (startIdx + s) % n;
    if (columns[idx].length === 0) return idx;
  }
  return -1;
}

function findSlotTarget(columns, color) {
  for (let i = 0; i < columns.length; i++) {
    if (columns[i].length > 0 && columns[i][columns[i].length - 1] === color) return i;
  }
  for (let i = 0; i < columns.length; i++) {
    if (columns[i].length === 0) return i;
  }
  return -1;
}

function stepState(state, action, targetCount) {
  const columns = state.columns.map(c => [...c]);
  let slot = state.slot;
  if (action.type === 'col') {
    const idx = action.idx;
    const col = columns[idx];
    if (col.length === 0) return null;
    const k = getBottomGroupCount(col);
    const color = col[col.length - 1];
    const t = findColTarget(columns, color, idx);
    if (t !== -1) {
      col.splice(col.length - k, k);
      for (let i = 0; i < k; i++) columns[t].push(color);
      if (columns[t].length === targetCount && getBottomGroupCount(columns[t]) === targetCount) {
        columns[t] = [];
      }
      return { columns, slot };
    }
    if (!slot) {
      col.pop();
      slot = color;
      return { columns, slot };
    }
    return null;
  } else {
    if (!slot) return null;
    const t = findSlotTarget(columns, slot);
    if (t === -1) return null;
    const color = slot;
    slot = null;
    columns[t].push(color);
    if (columns[t].length === targetCount && getBottomGroupCount(columns[t]) === targetCount) {
      columns[t] = [];
    }
    return { columns, slot };
  }
}

function serialize(state) {
  return JSON.stringify(state);
}

function isWin(state) {
  return !state.slot && state.columns.every(c => c.length === 0);
}

// Find all simple (no repeated state) winning paths
function findAllSimpleWinPaths(initialState, targetCount, maxDepth = 12) {
  const paths = [];
  function dfs(state, visited, path) {
    if (isWin(state)) {
      paths.push(path);
      return;
    }
    if (path.length >= maxDepth) return;
    const actions = [];
    for (let i = 0; i < state.columns.length; i++) actions.push({ type: 'col', idx: i, label: 'C' + (i + 1) });
    actions.push({ type: 'slot', label: 'Slot' });
    for (const a of actions) {
      const next = stepState(state, a, targetCount);
      if (!next) continue;
      const key = serialize(next);
      if (visited.has(key)) continue;
      visited.add(key);
      dfs(next, visited, [...path, a.label]);
      visited.delete(key);
    }
  }
  const initKey = serialize(initialState);
  dfs(initialState, new Set([initKey]), []);
  return paths;
}

// Test random 3-col, 3-color, 3-cards-per-color configurations
const cards = ['R','R','R','Y','Y','Y','B','B','B'];
function shuffle(a) {
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

const seen = new Set();
for (let iter = 0; iter < 50000; iter++) {
  const s = shuffle([...cards]);
  const cols = [s.slice(0,3), s.slice(3,6), s.slice(6,9)];
  if (cols.some(c => getBottomGroupCount(c) === 3)) continue;
  const init = { columns: cols, slot: null };
  const key = serialize(init);
  if (seen.has(key)) continue;
  seen.add(key);
  const paths = findAllSimpleWinPaths(init, 3, 12);
  if (paths.length === 1) {
    console.log('FOUND EXACTLY 1 SIMPLE PATH:', JSON.stringify(cols), 'Path:', paths[0].join(' -> '));
    break;
  } else if (paths.length > 0 && paths.length <= 2) {
    console.log('Paths count:', paths.length, JSON.stringify(cols), paths.map(p => p.join('->')));
  }
}
