      updateUI();
    }

    function updateUI() {
      const valid = countValidMoves();
      const remaining = columns.reduce((acc, c) => acc + c.length, 0) + (holdingSlot ? 1 : 0);

      container.classList.remove('win-state', 'dead-state');
      if (remaining === 0) {
        container.classList.add('win-state');
      } else if (valid === 0) {
        container.classList.add('dead-state');
      }

      document.getElementById('btn-undo').disabled = (history.length === 0 || isAnimating);

      const dots = document.querySelectorAll('.dot');
      dots.forEach((d, i) => {
        if (i === currentLevelIdx) d.classList.add('active');
        else d.classList.remove('active');
      });
    }

    function initLevel(idx) {
      currentLevelIdx = idx;
      const lvl = LEVELS[idx];
      columns = lvl.columns.map(c => [...c]);
      holdingSlot = null;
      history = [];
      isAnimating = false;
      activeTweens.length = 0;
