        mesh.position.z = THREE.MathUtils.lerp(startPos.z, endPos.z, p);
        const base = THREE.MathUtils.lerp(startPos.y, endPos.y, p);
        const arc = 4 * peakHeight * p * (1 - p);
        mesh.position.y = base + arc;
        mesh.rotation.x = Math.sin(p * Math.PI) * 0.18;
