    function animateClearColumn(colIdx, onComplete) {
      const meshes = cardMeshesByColumn[colIdx];
      cardMeshesByColumn[colIdx] = [];

      meshes.forEach((m) => {
        const startY = m.position.y;
        addTween(0.35, (p) => {
          m.position.y = startY + p * 2.2;
          m.rotation.y = p * Math.PI;
          const s = Math.max(0.001, 1 - p * 1.1);
          m.scale.set(s, s, s);
        }, () => {
          scene.remove(m);
        });
      });

      setTimeout(() => {
        if (onComplete) onComplete();
      }, 350);
    }

    function shakeColumn3D(colIdx) {
      const meshes = cardMeshesByColumn[colIdx];
      if (!meshes || meshes.length === 0) return;
      const origX = COL_X[colIdx];
      addTween(0.25, (p) => {
        const offset = Math.sin(p * Math.PI * 4) * 0.18 * (1 - p);
        meshes.forEach(m => m.position.x = origX + offset);
      }, () => {
        meshes.forEach(m => m.position.x = origX);
      });
    }

    function shakeSlot3D() {
      if (!slotCardMesh) return;
      const origX = SLOT_POS.x;
      addTween(0.25, (p) => {
        const offset = Math.sin(p * Math.PI * 4) * 0.18 * (1 - p);
        slotCardMesh.position.x = origX + offset;
      }, () => {
        slotCardMesh.position.x = origX;
