    async function handleColumnClick(colIdx) {
      if (isAnimating) return;
      const col = columns[colIdx];
      if (col.length === 0) return;

      const count = getBottomGroupCount(col);
      const color = col[col.length - 1];
      const match = findTargetColumnForColumnClick(color, colIdx);

      // 1. Move group to matching column or empty column
      if (match) {
        history.push(cloneState());
        isAnimating = true;

        const targetIdx = match.targetIdx;
        const targetCol = columns[targetIdx];
        const initialTargetLen = targetCol.length;

        col.splice(col.length - count, count);
        for (let i = 0; i < count; i++) {
          targetCol.push(color);
        }

        const movingMeshes = cardMeshesByColumn[colIdx].splice(cardMeshesByColumn[colIdx].length - count, count);

        let finished = 0;
        movingMeshes.forEach((mesh, idx) => {
          const start = mesh.position.clone();
          const targetCardIdx = initialTargetLen + idx;
          const end = getCardTargetPosition(targetIdx, targetCardIdx);
          cardMeshesByColumn[targetIdx].push(mesh);

          setTimeout(() => {
            animateArc(mesh, start, end, 0.28, 2.2, () => {
              finished++;
              if (finished === count) {
                if (isPureFullColumn(targetCol)) {
