            updateUI();
          });
        } else {
          isAnimating = false;
          updateUI();
        }
      });
    }

    function undoMove() {
      if (history.length === 0 || isAnimating) return;
      const prev = history.pop();
      columns = prev.columns;
      holdingSlot = prev.holdingSlot;
      rebuild3DScene();
    }

    function resetLevel() {
      if (isAnimating) return;
      initLevel(currentLevelIdx);
    }

    function nextLevel() {
      if (isAnimating) return;
      initLevel((currentLevelIdx + 1) % LEVELS.length);
    }

    // --- RAYCASTING MOUSE / TOUCH EVENTS ---
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    function onPointerDown(event) {
      if (isAnimating) return;
      const rect = canvas.getBoundingClientRect();
      const clientX = event.clientX !== undefined ? event.clientX : (event.touches && event.touches[0].clientX);
      const clientY = event.clientY !== undefined ? event.clientY : (event.touches && event.touches[0].clientY);
      if (clientX === undefined || clientY === undefined) return;

      mouse.x = ((clientX - rect.left) / rect.width) * 2 - 1;
      mouse.y = -((clientY - rect.top) / rect.height) * 2 + 1;

      raycaster.setFromCamera(mouse, camera);
      const intersects = raycaster.intersectObjects(interactivePlanes);

